using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class CalculatePayableTotalTests
{
    // Subtotals and payables are expressed in whole cents to avoid floating point rounding issues.
    [Theory]
    [InlineData("Bronze", 4999, 4750)]
    [InlineData("Bronze", 5000, 4700)]
    [InlineData("Silver", 19999, 18400)]
    [InlineData("Silver", 20000, 18000)]
    [InlineData("Gold", 2000, 1820)]
    [InlineData("Gold", 10000, 9000)]
    [InlineData("Gold", 20000, 18000)]
    [InlineData("Silver", 3010, 2800)]
    [InlineData("Bronze", 25012, 23012)]
    public void PayableTotalVariesByLoyaltyTierAndOrderSize(string tier, int subtotalCents, int expectedPayableCents)
    {
        var sut = new CalculatePayableTotal();

        var payableCents = sut.For(tier, subtotalCents);

        Assert.Equal(expectedPayableCents, payableCents);
    }
}

